sys_script_fix.script:
// Diagnostic script to check existing UI Policies and fields
(function executeFixScript() {

    gs.log("=== DIAGNOSTIC SCRIPT START ===");

    // 1. Check all UI Policies on change_request table
    gs.log("--- Checking UI Policies for change_request ---");
    var policies = new GlideRecord('sys_ui_policy');
    policies.addQuery('table', 'change_request');
    policies.query();

    while (policies.next()) {
        gs.log("UI Policy Found: " + policies.short_description + 
               " | Active: " + policies.active + 
               " | Conditions: " + policies.conditions +
               " | ID: " + policies.sys_id);
    }

    // 2. Check all UI Policy Actions for change_request
    gs.log("--- Checking UI Policy Actions for change_request ---");
    var actions = new GlideRecord('sys_ui_policy_action');
    actions.addQuery('ui_policy.table', 'change_request');
    actions.query();

    while (actions.next()) {
        var policy = actions.ui_policy.getDisplayValue();
        gs.log("UI Policy Action: Policy = " + policy + 
               " | Field = " + actions.field + 
               " | Visible = " + actions.visible +
               " | Mandatory = " + actions.mandatory);
    }

    // 3. Check custom fields on change_request
    gs.log("--- Checking Custom Fields on change_request ---");
    var fields = new GlideRecord('sys_dictionary');
    fields.addQuery('name', 'change_request');
    fields.addQuery('element', 'STARTSWITH', 'u_');
    fields.query();

    while (fields.next()) {
        gs.log("Custom Field: " + fields.element + 
               " | Label: " + fields.column_label +
               " | Type: " + fields.internal_type);
    }

    // 4. Check for fields that might match what we see in the form
    gs.log("--- Checking for 'destination' related fields ---");
    var destFields = new GlideRecord('sys_dictionary');
    destFields.addQuery('name', 'change_request');
    destFields.addQuery('element', 'CONTAINS', 'destination');
    destFields.query();

    while (destFields.next()) {
        gs.log("Destination Field: " + destFields.element + 
               " | Label: " + destFields.column_label +
               " | Type: " + destFields.internal_type);
    }

    gs.log("=== DIAGNOSTIC SCRIPT END ===");

})();
